import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

public class DelegatingDeviceTracker {

    private final ConcurrentHashMap<String, Position> gadgetPositions = new ConcurrentHashMap<>();

    public DelegatingDeviceTracker(Map<String, Position> initialPositions) {
        if(initialPositions != null) {
            initialPositions.forEach((id, position) -> addGadgetPosition(id, position));
        }
    }

    private void addGadgetPosition(String id, Position position) {
        gadgetPositions.putIfAbsent(id, position);
    }

    public Position getGadgetPosition(String id) {
        return gadgetPositions.get(id);
    }

    public boolean updateGadgetPosition(String id, Position newPosition) {
        if(gadgetPositions.containsKey(id)) {
            gadgetPositions.replace(id, newPosition);
            return true;
        }
        return false;
    }

    public Map<String, Position> getAllGadgetsPositionsLive() {
        return ConcurrentHashMap.newKeySet(gadgetPositions.entrySet().stream()
                .map(entry -> new AbstractMap.SimpleImmutableEntry<>(entry.getKey(), entry.getValue()))
                .collect(Collectors.toList()));
    }

    public Map<String, Position> getAllGadgetsPositionsStatic() {
        return gadgetPositions.entrySet().stream()
                .filter(entry -> gadgetPositions.containsKey(entry.getKey()))
                .collect(Collectors.toUnmodifiableMap(Map.Entry::getKey, Map.Entry::getValue));
    }

