import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class ParcelLocker {

    public static void main(String[] args) {
        Locker locker1 = new Locker();
        Locker locker2 = new Locker();

        // Create two threads for moving parcels between lockers
        Thread thread1 = new Thread(() -> moveParcel(locker1, locker2, 5, 1000, TimeUnit.MILLISECONDS));
        Thread thread2 = new Thread(() -> moveParcel(locker2, locker1, 10, 1000, TimeUnit.MILLISECONDS));

        // Start threads
        thread1.start();
        thread2.start();
    }

    public static boolean tryLockWithTimeout(ReentrantLock lock, long timeout, TimeUnit unit) {
        long startTime = System.nanoTime();

        while (true) {
            if (lock.tryLock()) return true;

            // Calculate remaining time
            long elapsedTime = System.nanoTime() - startTime;
            long remainingTime = Math.max(0, unit.toNanos(timeout) - elapsedTime);

            // If timeout has expired, break the loop and return false
            if (remainingTime <= 0) return false;

            try {
                Thread.sleep(randomPause());
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        }
    }

    public static long fixedPause() {
        return TimeUnit.SECONDS.toNanos(1);
    }

    public static long randomPause() {
        // Generate a random number between 100 and 500 milliseconds
        return TimeUnit.MILLISECONDS.toNanos((long) (Math.random() * 400 + 100));
    }

    public static void moveParcel(Locker sourceLocker, Locker targetLocker, int quantity, long timeout, TimeUnit unit) {
        // Attempt to acquire locks with a timeout
        boolean acquiredSourceLock = tryLockWithTimeout(sourceLocker.lock, timeout, unit);
        boolean acquiredTargetLock = false;

        if (acquiredSourceLock) {
            try {
                // Check if there are enough items in the source locker before attempting to acquire target lock
                if (sourceLocker.parcelCount.get() >= quantity) {
                    acquiredTargetLock = tryLockWithTimeout(targetLocker.lock, timeout, unit);

                    if (acquiredTargetLock) {
                        try {
                            // Move the parcel
                            sourceLocker.parcelCount.decrement(quantity);
                            targetLocker.parcelCount.increment(quantity);
                        } finally {
                            // Release the target locker lock in case of an exception during the move operation
                            targetLocker.lock.unlock();
                        }
                    } else throw new NotEnoughItemsException();
                } else throw new NotEnoughItemsException();
            } finally {
                // Release the source locker lock regardless of whether or not the parcel was moved successfully
                sourceLocker.lock.unlock();
            }
        }

        // If locks were not acquired, log an error message
        if (!acquiredSourceLock || !acquiredTargetLock) System.out.println("Unable to acquire all locks");
    }

    public static class NotEnoughItemsException extends RuntimeException {
        public NotEnoughItemsException() { super(); }

        public NotEnoughItemsException(String message) { super(message); }
    }

    public static class Locker {
        ReentrantLock lock = new ReentrantLock();
        ParcelCount parcelCount = new ParcelCount(0);
    }

    public static class ParcelCount {
        private volatile int count;

        public ParcelCount(int initialCount) {
            this.count = initialCount;
        }

        public void increment(int amount) {
            this.count += amount;
        }

        public void decrement(int amount) {
            if (amount > this.count) throw new IllegalStateException("Not enough items to decrement");

            this.count -= amount;
        }

        public int get() {
            return this.count;
        }
    }
}

