public class DeadlockAvoidance {
    private static final int MAX_ATTEMPTS = 5; // Maximum number of lock acquisition attempts

    public static void main(String[] args) throws Exception {
        Locker locker1 = new Locker(10); // Initial item count in first locker
        Locker locker2 = new Locker(15); // Initial item count in second locker

        Thread thread1 = new Thread(() -> move(locker1, locker2, 5, 10, TimeUnit.SECONDS));
        Thread thread2 = new Thread(() -> move(locker2, locker1, 10, 15, TimeUnit.SECONDS));

        // Start both threads
        thread1.start();
        thread2.start();

        // Wait for both threads to finish
        thread1.join();
        thread2.join();
    }

    public static boolean move(Locker source, Locker target, int quantity, long timeout, TimeUnit timeUnit) {
        ReentrantLock sourceLock = new ReentrantLock();
        ReentrantLock targetLock = new ReentrantLock();

        int attempt = 0;
        while (attempt < MAX_ATTEMPTS) {
            boolean sourceLocked = sourceLock.tryLock(timeout, timeUnit);
            boolean targetLocked = false;

            if (sourceLocked) {
                try {
                    targetLocked = targetLock.tryLock(timeout, timeUnit);

                    if (!targetLocked) { // If we couldn't get the target lock
                        Thread.sleep(getRandomDelay());
                        attempt++;
                        continue;
                    }

                    try {
                        if (source.getItemCount() < quantity) {
                            throw new NotEnoughItemsException("Not enough items in source locker");
                        }

                        // Perform the move operation here

                        return true; // Move was successful
                    } finally {
                        targetLock.unlock();
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt(); // Preserve interruption status
                    return false;
                } finally {
                    if (sourceLocked) sourceLock.unlock();
                }
            }

            Thread.sleep(getRandomDelay());
            attempt++;
        }

        return false; // Could not move the items within the timeout period
    }

    public static long getRandomDelay() {
        return (long) (Math.random() * 1000); // Random delay between 0 and 999 milliseconds
    }
