                    throw new NotEnoughItemsException("Not enough items in the locker.");
                }

                source.parcelCount.addAndGet(-quantity);
                target.parcelCount.addAndGet(quantity);

                return true;
            } finally {
                target.unlock();
                source.unlock();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException(e);
        }
    }

