import java.util.concurrent.*;
import java.util.Random;
import java.util.concurrent.locks.ReentrantLock;

public class WidgetConcurrent {
    private static final Random RANDOM = new Random();
    private static final int MAX_WIDGETS_IN_BIN = 5;

    public static void main(String[] args) throws InterruptedException, TimeoutException {
        Bin bin1 = new Bin("Bin1");
        Bin bin2 = new Bin("Bin2");

        Thread moveWidgetsThread = new Thread(() -> {
            try {
                if (!moveWidgets(bin1, bin2, 3, 5, TimeUnit.SECONDS)) {
                    System.out.println("Failed to move widgets within timeout.");
                }
            } catch (NotEnoughWidgetsException e) {
                System.out.println(e.getMessage());
            }
        });

        Thread emptyBinThread = new Thread(() -> {
            try {
                bin1.emptyBin();
            } finally {
                bin1.unlock();
            }
        });

        ExecutorService executorService = Executors.newFixedThreadPool(2);
        executorService.execute(moveWidgetsThread);
        executorService.execute(emptyBinThread);

        executorService.shutdown();
    }

    public static boolean moveWidgets(Bin source, Bin target, int widgetCount, long timeout, TimeUnit timeUnit)
            throws NotEnoughWidgetsException {
        if (!source.tryLock()) {
            throw new TimeoutException("Failed to acquire lock on " + source.getName() + ".");
        }
        try {
            if (!target.tryLock(timeout, timeUnit)) {
                return false;
            }

            try {
                if (widgetCount > source.getWidgetCount()) {
                    throw new NotEnoughWidgetsException("Not enough widgets in bin: " + source.getWidgetCount());
                }

                source.removeWidgets(widgetCount);
                target.addWidgets(widgetCount);
            } finally {
                target.unlock();
            }
        } finally {
            source.unlock();
        }
        return true;
    }

    public static class Bin {
        private final ReentrantLock lock = new ReentrantLock();
        private final String name;
        private int widgetCount;

        public Bin(String name) {
            this.name = name;
            this.widgetCount = MAX_WIDGETS_IN_BIN;
        }

        public void addWidgets(int count) {
            this.widgetCount += count;
        }

        public void removeWidgets(int count) throws NotEnoughWidgetsException {
            if (count > widgetCount) {
                throw new NotEnoughWidgetsException("Not enough widgets to remove.");
            }
            this.widgetCount -= count;
        }

        public int getWidgetCount() {
            return widgetCount;
        }

        public String getName() {
            return name;
        }

        public void emptyBin() throws TimeoutException {
            try {
                lock.lock();
                if (widgetCount > 0) {
                    throw new TimeoutException("Bin is not empty.");
                }
            } finally {
                lock.unlock();
            }
        }

        public void unlock() {
            lock.unlock();
        }

        public boolean tryLock() {
            return lock.tryLock();
        }

        public boolean tryLock(long time, TimeUnit unit) throws InterruptedException {
            return lock.tryLock(time, unit);
        }
    }

    public static class NotEnoughWidgetsException extends Exception {
        public NotEnoughWidgetsException(String message) {
            super(message);
        }
    }
}

import java.util.concurrent.*;
