class NotEnoughWidgetsException extends Exception {}

public class WidgetBinGame {
    private static final Random rand = new Random();

    public static void main(String[] args) throws InterruptedException, TimeoutException {
        Bin bin1 = new Bin(10);
        Bin bin2 = new Bin(5);

        try {
            if(move(bin1, bin2, 3, 2000, TimeUnit.MILLISECONDS)) {
                System.out.println("Move successful.");
            } else {
                System.out.println("Failed to acquire lock in time.");
            }
        } catch (NotEnoughWidgetsException e) {
            System.out.println(e.getMessage());
        }
    }

    public static boolean move(Bin source, Bin target, int numWidgetsToMove,
                                 long timeout, TimeUnit unit)
                                    throws InterruptedException, TimeoutException {
        if (numWidgetsToMove <= 0) throw new IllegalArgumentException("Number of widgets to move must be positive.");

        Lock lockSource = source.lock;
        Lock lockTarget = target.lock;

        boolean success = false;
        try {
            int acquiredLocks = 0;

            while (!success && acquiredLocks < 2) {
                if (lockSource.tryLock(timeout, unit)) {
                    acquiredLocks++;
                    Thread.sleep(randomPause());
                }

                if (lockTarget.tryLock(timeout, unit)) {
                    acquiredLocks++;
                    Thread.sleep(randomPause());

                    if(source.count.get() >= numWidgetsToMove) {
                        source.count.decrement(numWidgetsToMove);
                        target.count.increment(numWidgetsToMove);
                        success = true;
                    } else {
                        throw new NotEnoughWidgetsException("Not enough widgets in the source bin.");
                    }
                }
            }

            return success;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new InterruptedException("Thread was interrupted while waiting for lock.");
        } finally {
            if (!success) {
                if(lockSource.isHeldByCurrentThread()) lockSource.unlock();
                if(lockTarget.isHeldByCurrentThread()) lockTarget.unlock();
            }
        }
    }

    public static int randomPause() {
        return rand.nextInt(100);
    }

    static class Bin {
        private final ReentrantLock lock = new ReentrantLock();
        private final WidgetCount count;

        public Bin(int initialCount) {
            this.count = new WidgetCount(initialCount);
        }
    }

    static class WidgetCount {
        private volatile int count;

        public WidgetCount(int count) {
            this.count = count;
        }

        public void increment(int amount) {
            count += amount;
        }

        public void decrement(int amount) {
            if (count < amount) throw new ArithmeticException("Not enough widgets.");
            count -= amount;
        }
    }
}

import java.util.concurrent.TimeUnit;
