        this.count += widgets;
    }

    public int get() {
        return this.count;
    }

    public boolean hasEnoughWidgets(int requiredWidgets) {
        return this.count >= requiredWidgets;
    }
}

class Bin {
    private final ReentrantLock lock = new ReentrantLock();
    private final WidgetCount widgetCount = new WidgetCount();

    public void put(int widgets) {
        this.lock.lock();
        try {
            this.widgetCount.add(widgets);
        } finally {
            this.lock.unlock();
        }
    }

    public boolean take(int widgets, long timeout, TimeUnit unit) throws InterruptedException {
        if (!this.lock.tryLock(timeout, unit)) return false;
        try {
            if (this.widgetCount.hasEnoughWidgets(widgets)) {
                this.widgetCount.add(-widgets);
                return true;
            } else {
                throw new NotEnoughWidgetsException("Not enough widgets in bin.");
            }
        } finally {
            this.lock.unlock();
        }
    }
}

class NotEnoughWidgetsException extends Exception {
    public NotEnoughWidgetsException(String message) {
        super(message);
    }
}

