    public static boolean move(Bin source, Bin target, int numWidgetsToMove,
                                 long timeout, TimeUnit unit)
                                    throws InterruptedException, TimeoutException {
        if (numWidgetsToMove <= 0) throw new IllegalArgumentException("Number of widgets to move must be positive.");

        Lock lockSource = source.lock;
        Lock lockTarget = target.lock;

        boolean success = false;
        try {
            int acquiredLocks = 0;

            while (!success && acquiredLocks < 2) {
                if (lockSource.tryLock(timeout, unit)) {
                    acquiredLocks++;
                    Thread.sleep(randomPause());
                }

                if (lockTarget.tryLock(timeout, unit)) {
                    acquiredLocks++;
                    Thread.sleep(randomPause());

                    if(source.count.get() >= numWidgetsToMove) {
                        source.count.decrement(numWidgetsToMove);
                        target.count.increment(numWidgetsToMove);
                        success = true;
                    } else {
                        throw new NotEnoughWidgetsException("Not enough widgets in the source bin.");
                    }
                }
            }

            return success;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new InterruptedException("Thread was interrupted while waiting for lock.");
        } finally {
            if (!success) {
                if(lockSource.isHeldByCurrentThread()) lockSource.unlock();
                if(lockTarget.isHeldByCurrentThread()) lockTarget.unlock();
            }
        }
    }

    public static int randomPause() {
