        try {
            this.widgetCount.add(widgets);
        } finally {
            this.lock.unlock();
        }
    }

    public boolean take(int widgets, long timeout, TimeUnit unit) throws InterruptedException {
        if (!this.lock.tryLock(timeout, unit)) return false;
