import java.util.*;
import java.util.concurrent.*;

public class PublishingVehicleTracker {

    private ConcurrentHashMap<String, SafePoint> vehiclePositions = new ConcurrentHashMap<>();

    public static void main(String[] args) {
        // Assuming a fixed number of vehicles and positions for simplicity
        String[] vehicles = {"car1", "car2", "car3"};
        int[][] coordinates = {{10, 20}, {30, 40}, {50, 60}};

        PublishingVehicleTracker tracker = new PublishingVehicleTracker();

        // Adding vehicles to the tracker in a separate thread
        ExecutorService executorService = Executors.newFixedThreadPool(2);
        for (int i = 0; i < vehicles.length; i++) {
            final int index = i;
            executorService.submit(() -> tracker.addVehicle(vehicles[index], coordinates[index][0], coordinates[index][1]));
        }
        executorService.shutdown();

        // Retrieving and updating vehicle positions in a separate thread
        for (String vehicle : vehicles) {
            Future<Integer[]> future = executorService.submit(() -> tracker.getAndSetPosition(vehicle, 100, 200));
            try {
                Integer[] position = future.get();
                System.out.println("Vehicle " + vehicle + " new position: (" + position[0] + ", " + position[1] + ")");
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        // Printing the full map in a separate thread
        executorService.submit(() -> tracker.printFullPositionMap());
    }

    public void addVehicle(String vehicleId, int x, int y) {
        vehiclePositions.put(vehicleId, new SafePoint(x, y));
    }

    public Integer[] getAndSetPosition(String vehicleId, int newX, int newY) throws ExecutionException, InterruptedException {
        if (!vehiclePositions.containsKey(vehicleId)) {
            throw new IllegalArgumentException("Vehicle ID does not exist.");
        }
        Future<Integer> future = Executors.newSingleThreadExecutor().submit(() -> vehiclePositions.get(vehicleId).getX());
        Integer currentX = null;
        try {
            currentX = future.get();
        } catch (Exception e) {
            e.printStackTrace();
        }

        if (currentX == null) {
            throw new ExecutionException(new IllegalStateException("Failed to retrieve the X position of the vehicle."));
        }

        vehiclePositions.get(vehicleId).setCoordinates(newX, newY);
        return new Integer[]{currentX, newY};
    }

    public void printFullPositionMap() {
        Map<String, SafePoint> unmodifiableVehiclePositions = Collections.unmodifiableMap(vehiclePositions);
        for (Map.Entry<String, SafePoint> entry : unmodifiableVehiclePositions.entrySet()) {
            System.out.println("Vehicle ID: " + entry.getKey() + ", Position: (" + entry.getValue().getX() + ", " + entry.getValue().getY() + ")");
        }
    }

    private static class SafePoint {
        private final AtomicInteger x;
        private final AtomicInteger y;

        public SafePoint(int initialX, int initialY) {
            this.x = new AtomicInteger(initialX);
            this.y = new AtomicInteger(initialY);
        }

        public int getX() {
            return x.get();
        }

        public int getY() {
            return y.get();
        }

        public void setCoordinates(int newX, int newY) {
            x.set(newX);
            y.set(newY);
        }
    }
}

