import java.util.*;
import java.util.concurrent.*;

public class RuneGrimoire {

    enum Rune {
        AQUA("Air"), FIRE("Fire"), WATER("Water"), EARTH("Earth");

        private final String constellation;

        Rune(String constellation) { this.constellation = constellation; }

        public String getConstellation() { return constellation; }

        static Comparator<Rune> COMPARATOR = (r1, r2) -> 
            Objects.compare(r1.getConstellation(), r2.getConstellation(), String::compareTo);
    }

    enum Resonance {
        UP("Up"), DOWN("Down"), LEFT("Left"), RIGHT("Right");

        private final String resonance;

        Resonance(String resonance) { this.resonance = resonance; }

        public String getResonance() { return resonance; }

        static Comparator<Resonance> COMPARATOR = (r1, r2) -> 
            Objects.compare(r1.getResonance(), r2.getResonance(), String::compareTo);
    }

    class Harmony {
        private final Rune rune;
        private final Resonance resonance;

        public Harmony(Rune rune, Resonance resonance) { this.rune = rune; this.resonance = resonance; }

        public boolean isCompatible(Harmony harmony) {
            return this.rune == harmony.getRune() && 
                (this.resonance == Resonance.UP && harmony.getResonance() == Resonance.DOWN ||
                 this.resonance == Resonance.DOWN && harmony.getResonance() == Resonance.UP ||
                 this.resonance == Resonance.LEFT && harmony.getResonance() == Resonance.RIGHT ||
                 this.resonance == Resonance.RIGHT && harmony.getResonance() == Resonance.LEFT);
        }

        public Rune getRune() { return rune; }
        public Resonance getResonance() { return resonance; }
    }

    class Grimoire {
        private final List<Harmony> runes = new ArrayList<>();

        public void crystallize(Collection<Rune> candidates) {
            ExecutorService service = Executors.newFixedThreadPool(2);
            try {
                List<List<Runnable>> tasks = candidates.stream()
                    .map(rune -> Collections.singletonList((Runnable)(() ->
                        this.runes.add(new Harmony(rune, findOppositeResonance(rune)))))
                    .collect(Collectors.toList());

                for (List<Runnable> taskGroup : tasks) {
                    List<Future<?>> futures = new ArrayList<>();
                    for (Runnable task : taskGroup) { 
                        Future<?> future = service.submit(task);
                        futures.add(future); 
                    }
                    // Wait until all tasks in the group are finished
                    for (Future<?> future : futures) { future.get(); }
                }

            } catch (Exception e) {
                throw new RuntimeException(e);
            } finally {
                service.shutdown();
            }
        }

        private Resonance findOppositeResonance(Rune rune) {
            List<Resonance> resonances = Arrays.asList(Resonance.values());
            Collections.shuffle(resonances);
            for (Resonance resonance : resonances) { 
                if (rune.getConstellation().equals(resonance.toString())) return resonance; }
            throw new RuntimeException("No opposite resonance found");
        }

        public int countValidHarmonies() {
            int harmonies = 0;
            for (int i=0; i<this.runes.size()-1; i++) {
                for (int j=i+1; j<this.runes.size(); j++) {
                    if (runes.get(i).isCompatible(runes.get(j))) { harmonies++; }
                }
            }
            return harmonies;
        }
    }

    public static void main(String[] args) throws Exception {
        RuneGrimoire grimoire = new RuneGrimoire();
        Grimoire g = grimoire.new Grimoire();

        // Sample runes and resonances
        List<Rune> candidates = Arrays.asList(Rune.AQUA, Rune.FIRE, Rune.WATER);
        g.crystallize(candidates);

        int numHarmonies = g.countValidHarmonies();
        System.out.println("Number of valid harmonies: " + numHarmonies);
    }
}

