        private final List<Harmony> harmonies = new ArrayList<>();

        void add(Harmony harmony) {
            harmonies.add(harmony);
        }

        int getNumRunes() {
            return harmonies.stream()
                              .mapToInt(h -> h.runes.size())
                              .sum();
        }
    }

    public static int channelTheGrimoire(List<Rune> runes) {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        final Grimoire grimoire = new Grimoire();

