public class GrimoireInscription {
    enum RuneConstellation {
        FIRE,
        WATER,
        EARTH,
        AIR
    }

    enum RuneResonance {
        PROGRESSIVE,
        RETROGRADE,
        CONSISTENT,
        INCONSISTENT
    }

    class Rune {
        private final RuneConstellation constellation;
        private final RuneResonance resonance;

        public Rune(RuneConstellation constellation, RuneResonance resonance) {
            this.constellation = constellation;
            this.resonance = resonance;
        }

        public RuneConstellation getConstellation() {
            return constellation;
        }

        public RuneResonance getResonance() {
            return resonance;
        }
    }

    class Harmony {
        private final List<Rune> runes;

        public Harmony(List<Rune> runes) {
            this.runes = Collections.unmodifiableList(new ArrayList<>(runes));
        }

        public boolean isValidHarmony() {
            for (int i = 0; i < runes.size() - 1; ++i) {
                Rune runeA = runes.get(i);
                Rune runeB = runes.get(i + 1);

                if (!runeA.getConstellation().equals(runeB.getConstellation()) ||
                    !runeA.getResonance().equals(getOppositeResonance(runeB.getResonance()))) {
                    return false;
                }
            }

            return true;
        }

        private RuneResonance getOppositeResonance(RuneResonance resonance) {
            switch (resonance) {
                case PROGRESSIVE:
                    return RuneResonance.RETROGRADE;
                case RETROGRADE:
                    return RuneResonance.PROGRESSIVE;
                case CONSISTENT:
                    return RuneResonance.INCONSISTENT;
