        @Override
        public int compare(Rune r1, Rune r2) {
            if (r1.constellation != r2.constellation)
                return r1.constellation.compareTo(r2.constellation);
            else
                return -Integer.compare(r1.resonance.ordinal(), r2.resonance.ordinal());
        }
    };

