            this.runes = Collections.unmodifiableList(new ArrayList<>(runes));
        }

        @Override
        public String toString() {
            return "Harmony{" + runes.stream().map(r -> r.toString()).reduce((r1, r2) -> r1 + ", " + r2).orElse("") + '}';
        }
    }

