        public Grimoire(List<Future<List<Harmony>>> harmonies) {
            this.harmonies = Collections.unmodifiableList(new ArrayList<>(harmonies));
        }

        @Override
        public String toString() {
            return "Grimoire{" + harmonies.stream().map(h -> h.toString()).reduce((h1, h2) -> h1 + ", " + h2).orElse("") + '}';
        }
    }

