class TransferRitual implements Callable<Vault> {
    private final int fromId, toId;
    private static final Object lock = new Object();

    public TransferRitual(int fromId, int toId) {
        this.fromId = fromId;
        this.toId = toId;
    }

    @Override
    public Vault call() throws Exception {
        int myId = Thread.currentThread().hashCode();
        int otherVaultId;

        if (myId == fromId) {
            otherVaultId = toId;
        } else if (myId == toId) {
            otherVaultId = fromId;
        } else {
            throw new AssertionError("Thread " + myId + " does not own a vault");
        }

        Vault myVault = new Vault(myId);
        Vault otherVault = new Vault(otherVaultId);

        if (myVault.getIdentityHashCode() == otherVault.getIdentityHashCode()) {
            synchronized (lock) {
                transferTreasure(myVault, otherVault);
            }
        } else {
            transferTreasure(myVault, otherVault);
        }

        return myVault;
    }

    private void transferTreasure(Vault fromVault, Vault toVault) throws InsufficientGoldException {
        GoldAmount amount = new GoldAmount(10); // Transfer 10 gold

        if (fromVault.getAmount().isLessThan(amount)) {
            throw new InsufficientGoldException("Not enough gold in the vault");
        }

        fromVault.debit(amount);
        toVault.credit(amount);

        System.out.println("Transferred " + amount + " gold from Vault #" + fromVault.getIdentityHashCode() +
                " to Vault #" + toVault.getIdentityHashCode());
    }
}

class Vault {
    private final int identityHashCode;
    private GoldAmount amount = new GoldAmount(0); // Assume initial amount is 0

