    public int getIdentityHashCode() {
        return identityHashCode;
    }

    public GoldAmount getAmount() {
        return amount;
    }

    public void debit(GoldAmount amount) {
        if (amount.isLessThan(this.amount)) {
            throw new IllegalStateException("Debit amount cannot be greater than current amount");
        }
        this.amount = amount.subtract(this.amount);
    }

    public void credit(GoldAmount amount) {
        this.amount = this.amount.add(amount);
    }
}

class GoldAmount implements Comparable<GoldAmount> {
