class GemTransferHelper {
    private final Hoard source;
    private final Hoard target;
    private final GemAmount amount;

    public GemTransferHelper(Hoard source, Hoard target, GemAmount amount) {
        this.source = source;
        this.target = target;
        this.amount = amount;
    }

    public void performRitual() throws InsufficientGemsException {
        if (source.getId() < target.getId()) {
            source.withdraw(amount);
            target.deposit(amount);
        } else if (source.getId() > target.getId()) {
            target.withdraw(amount);
            source.deposit(amount);
        } else { // Same ID, use secondary lock
            synchronized (this) {
                source.withdraw(amount);
                target.deposit(amount);
            }
        }
    }

    public int getSourceId() {
        return source.getId();
    }

    public int getTargetId() {
        return target.getId();
    }
