```java
import java.util.*;
import java.util.concurrent.*;

public class ChronomanticDragonTracker {

    private final Constellation<String, MutableOrb> constellations;

    public ChronomanticDragonTracker(Constellation<String, MutableOrb> constellations) {
        if (constellations == null) {
            throw new IllegalArgumentException("Initial constellation cannot be null");
        }
        this.constellations = deepClone(constellations);
    }

    public synchronized Constellation<String, MutableOrb> getConstellations() {
        return deepClone(this.constellations);
    }

    public synchronized MutableOrb getOrb(String sigil) {
        if (sigil == null) {
            throw new IllegalArgumentException("Sigil cannot be null");
        }
        MutableOrb orb = constellations.get(sigil);
        return orb != null ? new MutableOrb(orb) : null;
    }

    public synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
        if (sigil == null || !constellations.containsKey(sigil)) {
            throw new IllegalArgumentException("Sigil not found or invalid");
        }
        MutableOrb orb = constellations.get(sigil);
        orb.setShimmer(shimmerX, shimmerY);
    }

    private synchronized Constellation<String, MutableOrb> deepClone(Constellation<String, MutableOrb> original) {
        Map<String, MutableOrb> newOrbs = new HashMap<>();
        for (Map.Entry<String, MutableOrb> entry : original.entrySet()) {
            newOrbs.put(entry.getKey(), new MutableOrb(entry.getValue()));
        }
        return Constellation.of(newOrbs);
    }

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(3);

        final Constellation<String, MutableOrb> constellations = Constellation.of(
                "dragon1", new MutableOrb(5, 10),
                "dragon2", new MutableOrb(15, 20));

        ChronomanticDragonTracker tracker = new ChronomanticDragonTracker(constellations);

        Runnable task1 = () -> {
            try {
                Thread.sleep(1000);
                System.out.println("Thread 1 - " + tracker.getOrb("dragon1"));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Runnable task2 = () -> {
            try {
                Thread.sleep(2000);
                tracker.setOrb("dragon2", 25, 30);
                System.out.println("Thread 2 - " + tracker.getOrb("dragon2"));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Runnable task3 = () -> {
            try {
                Thread.sleep(3000);
                System.out.println("Thread 3 - " + tracker.getConstellations());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        executor.submit(task1);
        executor.submit(task2);
        executor.submit(task3);

        executor.shutdown();
        executor.awaitTermination(10, TimeUnit.SECONDS);
    }

    static class MutableOrb {
        private int shimmerX;
        private int shimmerY;

        public MutableOrb(MutableOrb other) {
            this.shimmerX = other.shimmerX;
            this.shimmerY = other.shimmerY;
        }

        public void setShimmer(int shimmerX, int shimmerY) {
            this.shimmerX = shimmerX;
            this.shimmerY = shimmerY;
        }

        @Override
        public String toString() {
            return "MutableOrb{" + "shimmerX=" + shimmerX + ", shimmerY=" + shimmerY + '}';
        }
    }

    static class Constellation<K, V> extends AbstractMap<K, V> {
        private final Map<K, V> delegate;

        public Constellation(Map<K, V> map) {
            this.delegate = Collections.unmodifiableMap(new HashMap<>(map));
        }

        @Override
        public Set<Entry<K, V>> entrySet() {
            return delegate.entrySet();
        }

        public static <K, V> Constellation<K, V> of(K key1, V value1, K key2, V value2) {
            Map<K, V> map = new HashMap<>();
            map.put(key1, value1);
            map.put(key2, value2);
            return new Constellation<>(map);
        }
    }
}
