import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class SummonChaosOrbs {

    static final int ORBS_NUMBER = 5;
    static final int THREADS_NUMBER = 2;
    static final int ITERATIONS_NUMBER = 10;
    private static Random random = new Random();
    private static ExecutorService executorService =
            Executors.newFixedThreadPool(THREADS_NUMBER);

    public static void main(String[] args) {
        Orb[] orbs = new Orb[ORBS_NUMBER];
        for (int i = 0; i < ORBS_NUMBER; ++i) {
            orbs[i] = new Orb(i);
        }

        for (int i = 0; i < THREADS_NUMBER; ++i) {
            executorService.execute(new FluxThread(orbs));
        }

        executorService.shutdown();
    }

    private static class FluxThread extends Thread {
        private final Orb[] orbs;

        FluxThread(Orb[] orbs) {
            this.orbs = orbs;
        }

        @Override
        public void run() {
            for (int j = 0; j < ITERATIONS_NUMBER; ++j) {
                int fromIndex, toIndex;
                do {
                    fromIndex = random.nextInt(ORBS_NUMBER);
                    toIndex = random.nextInt(ORBS_NUMBER);
                } while (fromIndex == toIndex);

                Orb from = orbs[fromIndex];
                Orb to = orbs[toIndex];

                try {
                    EtherealFlux.transferEnergy(from, to, ManaShard.values()[random.nextInt(ManaShard.values().length)]);
                } catch (InsufficientManaException e) {
                    // ignored
                }
            }
        }
    }

    private static class Orb {
        private int id;
        private int mana;

        public Orb(int id) {
            this.id = id;
            this.mana = 1000; // default value
