```java
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.Random;

public class GoblinGoldShuffle {
    private static final int NUM_POUCHES = 5;
    private static final int ITERATIONS_PER_THREAD = 10;

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        PouchManager pouchManager = new PouchManager();
        for (int i = 0; i < NUM_POUCHES; i++) {
            pouchManager.addPouch(new GoblinPouch(pouchManager));
        }
        for (int i = 0; i < 2; i++) {
            executor.submit(new TradeThread(pouchManager, ITERATIONS_PER_THREAD));
        }
        executor.shutdown();
    }

    private static class PouchManager {
        private final GoblinPouch[] pouches;

        public PouchManager() {
            this.pouches = new GoblinPouch[NUM_POUCHES];
        }

        public void addPouch(GoblinPouch pouch) {
            for (int i = 0; i < NUM_POUCHES; i++) {
                if (pouches[i] == null) {
                    pouches[i] = pouch;
                    break;
                }
            }
        }

        public synchronized GoblinPouch getPouch(int index) {
            return pouches[index];
        }
    }

    private static class TradeThread extends Thread {
        private final PouchManager pouchManager;
        private final int iterations;

        public TradeThread(PouchManager pouchManager, int iterations) {
            this.pouchManager = pouchManager;
            this.iterations = iterations;
        }

        @Override
        public void run() {
            Random random = new Random();
            for (int i = 0; i < iterations; i++) {
                int fromIndex = random.nextInt(NUM_POUCHES);
                int toIndex = random.nextInt(NUM_POUCHES);
                while (fromIndex == toIndex) {
                    toIndex = random.nextInt(NUM_POUCHES);
                }
                try {
                    SneakyTrade.transferGold(pouchManager.getPouch(fromIndex), pouchManager.getPouch(toIndex));
                } catch (InsufficientGoldException e) {
                    // Ignore
                }
            }
        }
    }

    public static class GoblinPouch {
        private final PouchManager manager;
        private int goldAmount;

        public GoblinPouch(PouchManager manager) {
            this.manager = manager;
            this.goldAmount = 1000; // Default value
        }

        public synchronized void addGold(int amount) {
            goldAmount += amount;
        }

        public synchronized void removeGold(int amount) throws InsufficientGoldException {
            if (goldAmount < amount) {
                throw new InsufficientGoldException();
            }
            goldAmount -= amount;
        }

        @Override
        public String toString() {
            return "GoblinPouch{" +
                    "goldAmount=" + goldAmount +
                    '}';
        }
    }

    public static class SneakyTrade {
        public static void transferGold(GoblinPouch from, GoblinPouch to) throws InsufficientGoldException {
            int amount = (int) (Math.random() * 100);
            from.removeGold(amount);
            to.addGold(amount);
        }
    }

    public static class InsufficientGoldException extends Exception {
    }
}
```
This code provides a simple simulation of gold trades between goblin poches. Each thread performs random swaps within the given limits and handles any exceptions thrown by the `SneakyTrade.transferGold` method.

