import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class QuantumCAS {
    private int shardLevel = 0;

    public synchronized int compareAndSwap(int expected, int newValue) {
        if (shardLevel == expected) {
            shardLevel = newValue;
            return expected;
        }
        return shardLevel;
    }

    public synchronized int getShardLevel() {
        return shardLevel;
    }
}

public class StarlightShardCounter {

    private QuantumCAS quantumCAS;

    public StarlightShardCounter() {
        this.quantumCAS = new QuantumCAS();
    }

    public synchronized int getShardLevel() {
        return quantumCAS.getShardLevel();
    }

    public synchronized void gatherShard(int expected, int newValue) {
        while (true) {
            int shardLevel = quantumCAS.compareAndSwap(expected, newValue);
            if (shardLevel == expected)
                break;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        StarlightShardCounter counter = new StarlightShardCounter();

        ExecutorService executorService = Executors.newFixedThreadPool(2);

        for (int i = 0; i < 10; i++) {
            executorService.submit(new Runnable() {
                @Override
                public void run() {
                    int shardLevelToCollect = counter.getShardLevel();
                    if (shardLevelToCollect == 100) return;
                    System.out.println("Thread " + Thread.currentThread().getId() + ": Collecting shard level: "
                            + shardLevelToCollect);
                    counter.gatherShard(shardLevelToCollect, shardLevelToCollect + 1);
                }
            });
        }

        executorService.shutdown();
    }
}

import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class StarlightShardCounter {
    private int shardLevel = 0;
    private final QuantumCAS quantumCAS;
    private final Lock lock = new ReentrantLock();

    public StarlightShardCounter() {
        this.quantumCAS = new QuantumCAS();
    }

    public int getShardLevel() {
        return shardLevel;
    }

    public boolean gatherShard(int expected) {
        while (true) {
            if (shardLevel < expected) {
                lock.lock();
                try {
                    if (shardLevel >= expected) {
                        break;
                    }
                    shardLevel++;
                } finally {
                    lock.unlock();
                }
            } else {
                return quantumCAS.compareAndSwap(shardLevel, expected + 1);
            }
        }

        return false;
    }

    private static class QuantumCAS {
        public boolean compareAndSwap(int expected, int newValue) {
            if (expected == shardLevel.get()) {
                shardLevel.set(newValue);
                return true;
            } else {
                return false;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        StarlightShardCounter counter = new StarlightShardCounter();

        Thread thread1 = new Thread(() -> {
            for (int i = 0; i < 10; i++) {
                System.out.println(counter.getShardLevel());
            }
        });

        Thread thread2 = new Thread(() -> {
            for (int i = 0; i < 5; i++) {
                counter.gatherShard(9);
            }
        });

        thread1.start();
        thread2.start();

        thread1.join();
        thread2.join();

        System.out.println("Final shard level: " + counter.getShardLevel());
    }
}

