            if (quantumCAS.compareAndSwap(expected, expected + 1)) {
                currentShardLevel = expected + 1;
                System.out.println("Collected a shard. Current shard level: " + currentShardLevel);
                break;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
