    public static void main(String[] args) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Account sourceAccount = new Account(1000.00);
        Account destinationAccount = new Account(500.00);

        Future<Boolean> transferFuture1 = executor.submit(() -> 
                tryTransfer(sourceAccount, destinationAccount, 200.00, 5, TimeUnit.SECONDS));

        Future<Boolean> transferFuture2 = executor.submit(() -> 
                tryTransfer(sourceAccount, destinationAccount, 300.00, 5, TimeUnit.SECONDS));

        System.out.println("Transfer 1 Successful: " + transferFuture1.get());
        System.out.println("Transfer 2 Successful: " + transferFuture2.get());

        executor.shutdown();
    }

    private static boolean tryTransfer(Account source, Account destination, double amount, long timeout, TimeUnit timeUnit) {
        ReentrantLock lock1 = source.getLock();
        ReentrantLock lock2 = destination.getLock();

        while (true) {
            if(lock1.tryLock()) {
                try {
                    if(lock2.tryLock()) {
                        try {
                            if(source.withdraw(amount)) {
                                destination.deposit(amount);
                                return true;
                            } else {
                                throw new InsufficientFundsException("Insufficient funds in source account");
                            }
                        } finally {
                            lock2.unlock();
                        }
                    } else {
                        if(!lock1.tryLock(getRandomTimeout(timeout, timeUnit), timeUnit)) return false;
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return false;
                } finally {
                    lock1.unlock();
                }
            } else {
                try {
                    if(!lock2.tryLock(getRandomTimeout(timeout, timeUnit), timeUnit)) return false;
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return false;
                }
            }
        }
    }

    private static long getRandomTimeout(long baseTime, TimeUnit unit){
        return RANDOM.nextInt((int)unit.toMillis(baseTime));
    }
