import java.util.concurrent.*;
import java.util.Random;
import java.util.function.*;

public class DeadlockAvoidance {

    public static void main(String[] args) {
        int account1Id = 1, account2Id = 2;

        Account account1 = new Account(account1Id);
        Account account2 = new Account(account2Id);

        ExecutorService executorService = Executors.newFixedThreadPool(3);

        // Thread for transferring money between accounts
        Runnable transferRunnable = () -> {
            try {
                performTransfer(executorService, account1, account2, 50, 5, TimeUnit.SECONDS);
            } catch (InsufficientFundsException | InterruptedException e) {
                System.err.println(e.getMessage());
            }
        };

        // Start the main thread
        executorService.submit(transferRunnable);

        // Shutdown the executor service after all threads have finished
        executorService.shutdown();
    }

    public static void performTransfer(ExecutorService executorService, Account sourceAccount,
                                          Account destinationAccount, int amountToTransfer, long timeout, TimeUnit timeUnit)
            throws InsufficientFundsException, InterruptedException {
        if (sourceAccount.getId() == destinationAccount.getId()) {
            throw new IllegalArgumentException("Source and destination accounts cannot be the same.");
        }

        Random random = new Random();
        boolean successful = false;

        try {
            long startTime = System.nanoTime();

            while (!successful) {
                long elapsedTime = TimeUnit.NANOSECONDS.toSeconds(System.nanoTime() - startTime);

                if (elapsedTime > timeout) {
                    System.out.println("Timeout occurred. Transfer operation canceled.");
                    return;
                }

                // Attempt to lock the source and destination accounts
                boolean acquiredSourceLock = sourceAccount.getReentrantLock().tryLock(timeout, timeUnit);
                boolean acquiredDestinationLock = destinationAccount.getReentrantLock().tryLock(timeout, timeUnit);

                if (acquiredSourceLock && acquiredDestinationLock) {
                    try {
                        // Check if sufficient funds are available in the source account
                        if (!sourceAccount.hasSufficientFunds(amountToTransfer)) {
                            throw new InsufficientFundsException("Insufficient funds to transfer.");
                        }

                        // Perform the money transfer operation
                        sourceAccount.withdraw(DollarAmount.fromInt(amountToTransfer));
                        destinationAccount.deposit(DollarAmount.fromInt(amountToTransfer));

                        successful = true;
                    } finally {
                        // Release both locks regardless of whether the transfer was successful or not
                        sourceAccount.getReentrantLock().unlock();
                        destinationAccount.getReentrantLock().unlock();
                    }
                }

                // Random backoff strategy before retrying to acquire locks
                if (!successful) {
                    Thread.sleep(random.nextInt(50));
                }
            }
        } catch (InterruptedException e) {
            System.err.println("Thread interrupted during account lock acquisition: " + e.getMessage());
            throw e;
        } finally {
            sourceAccount.getReentrantLock().unlock();
            destinationAccount.getReentrantLock().unlock();
        }

        System.out.println(String.format("Successfully transferred $%d from account #%d to account #%d.",
                amountToTransfer, sourceAccount.getId(), destinationAccount.getId()));
    }

    public static class DollarAmount {
        private final int amount;

        private DollarAmount(int amount) {
            this.amount = amount;
        }

        public static DollarAmount fromInt(int amount) {
            return new DollarAmount(amount);
        }

        @Override
        public String toString() {
            return "$" + amount;
        }
    }

    public static class Account {
        private final int id;
        private final ReentrantLock lock = new ReentrantLock();
        private final DollarAmount balance;

        public Account(int id) {
            this.id = id;
            this.balance = DollarAmount.fromInt(1000); // Initial balance
        }

        public int getId() {
            return id;
        }

        public ReentrantLock getReentrantLock() {
            return lock;
        }

        public DollarAmount getBalance() {
            return balance;
        }

        public void withdraw(DollarAmount amount) throws InsufficientFundsException {
            if (!hasSufficientFunds(amount.amount)) {
                throw new InsufficientFundsException("Insufficient funds to withdraw.");
            }
            balance.amount -= amount.amount;
        }

        public void deposit(DollarAmount amount) {
            balance.amount += amount.amount;
        }

        public boolean hasSufficientFunds(int amount) {
            return balance.amount >= amount;
        }
    }

    public static class InsufficientFundsException extends Exception {
        public InsufficientFundsException(String message) {
            super(message);
        }
    }
}

