public class BarrierTimer implements Runnable {

    private boolean started;
    private long startTime, endTime;

    @Override
    public synchronized void run() {
        if (!started) {
            this.startTime = System.nanoTime();
            this.started = true;
        } else {
            this.endTime = System.nanoTime();
        }
    }

    public synchronized void clear() {
        this.started = false;
    }

    public synchronized long getTime() {
        return this.endTime - this.startTime;
    }

    public static void main(String[] args) throws InterruptedException {
        BarrierTimer timer = new BarrierTimer();

        Thread thread1 = new Thread(timer);
        Thread thread2 = new Thread(timer);

        thread1.start();
        // Wait for the first thread to finish its task
        thread1.join();

        long time1 = timer.getTime();
        System.out.println("Time elapsed by thread 1: " + time1 + " nanoseconds");

        thread2.start();
        // Wait for the second thread to finish its task and calculate the time
        thread2.join();

        long time2 = timer.getTime();
        System.out.println("Time elapsed by thread 2: " + time2 + " nanoseconds");

        timer.clear();
    }
}

