            t.setDaemon(true);
            return t;
        });

        producerExecutor.submit(new Producer(buffer));
        consumerExecutor.submit(new Consumer(buffer));
        consumerExecutor.submit(new Consumer(buffer));

        producerExecutor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        consumerExecutor.shutdown();
    }
}

import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

public class BoundedBuffer {
    private final ReentrantLock lock = new ReentrantLock();
    private final Condition notFull = lock.newCondition();
    private final Condition notEmpty = lock.newCondition();

    private final String[] items = new String[3];
    private int count = 0;
    private int head = 0;
    private int tail = 0;

    public void put(String x) throws InterruptedException {
        lock.lock();
        try {
            while (count == items.length)
                notFull.await();

            items[tail] = x;
            if (++tail == items.length)
                tail = 0;
            count++;
            notEmpty.signal();
        } finally {
            lock.unlock();
        }
    }

    public String take() throws InterruptedException {
        lock.lock();
        try {
            while (count == 0)
                notEmpty.await();

            String x = items[head];
            if (++head == items.length)
                head = 0;
            count--;
            notFull.signal();
            return x;
        } finally {
            lock.unlock();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        BoundedBuffer buffer = new BoundedBuffer();

        Runnable producer = () -> {
            for (int i = 0; i < 5; i++) {
                try {
                    System.out.println("Produced: " + i);
                    buffer.put("" + i);
                    Thread.sleep(1000);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
        };

        Runnable consumer = () -> {
            for (int i = 0; i < 5; i++) {
                try {
                    System.out.println("Consumed: " + buffer.take());
                    Thread.sleep(1000);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
        };

        new Thread(producer).start();
        new Thread(consumer).start();
    }
}

import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicInteger;

public class BoundedBuffer {
    private Object[] items;
    private AtomicInteger count = new AtomicInteger(0);
    private final Semaphore notFull, notEmpty;

    public BoundedBuffer(int capacity) {
        this.items = new Object[capacity];
        this.notFull = new Semaphore(capacity);
        this.notEmpty = new Semaphore(0);
    }

    public void put(Object x) throws InterruptedException {
        notFull.acquire();
        synchronized (this) {
            items[count.getAndIncrement() % items.length] = x;
        }
        notEmpty.release();
    }

    public Object take() throws InterruptedException {
        notEmpty.acquire();
        synchronized (this) {
            return items[count.decrementAndGet() % items.length];
        }
    }

    public boolean isEmpty() {
        return count.get() == 0;
    }

    public boolean isFull() {
        return count.get() == items.length;
    }

    public static void main(String[] args) throws InterruptedException {
        BoundedBuffer buffer = new BoundedBuffer(2);

        Thread producer1 = new Thread(() -> {
            try {
                while (!buffer.isFull()) {
                    System.out.println("Producer 1: Putting " + Math.random());
                    buffer.put(Math.random());
                }
