                e.printStackTrace();
            }
        });

        Thread consumer1 = new Thread(() -> {
            try {
                while (!buffer.isEmpty()) {
                    System.out.println("Consumer 1: Taking " + buffer.take());
                }
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        });

        producer1.start();
        consumer1.start();

        producer1.join();
        consumer1.join();
    }
}

