import java.util.Set;

public class ServerStatusBeforeSplit {

    private final Set<String> users = new HashSet<>();
    private final Set<String> queries = new HashSet<>();

    public ServerStatusBeforeSplit() {
        // constructor logic here
    }

    public synchronized void addUser(String u) {
        users.add(u);
    }

    public synchronized void addQuery(String q) {
        queries.add(q);
    }

    public synchronized void removeUser(String u) {
        users.remove(u);
    }

    public synchronized void removeQuery(String q) {
        queries.remove(q);
    }

    private static class Worker implements Runnable {

        private final ServerStatusBeforeSplit server;

        public Worker(ServerStatusBeforeSplit server){
            this.server = server;
        }

        @Override
        public void run() {
            server.addUser("user1");
            server.addQuery("query1");

            try {
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }

            server.removeUser("user1");
            server.removeQuery("query1");
        }
    }

    public static void main(String[] args) {
        ServerStatusBeforeSplit server = new ServerStatusBeforeSplit();

        ExecutorService executor = Executors.newFixedThreadPool(2);

        for(int i=0; i<3; i++){
            executor.execute(new Worker(server));
        }

        executor.shutdown();
    }

}

