import java.util.HashSet;
import java.util.Set;

public class ServerStatusBeforeSplit {

    private Set<String> users = new HashSet<>();
    private Set<String> queries = new HashSet<>();

    public ServerStatusBeforeSplit() {
        addUser("user1");
        addQuery("query1");
    }

    // Synchronize methods to ensure thread safety
    public synchronized void addUser(String u) {
        this.users.add(u);
    }

    public synchronized void removeUser(String u) {
        this.users.remove(u);
    }

    public synchronized void addQuery(String q) {
        this.queries.add(q);
    }

    public synchronized void removeQuery(String q) {
        this.queries.remove(q);
    }

    public static void main(String[] args) throws InterruptedException {

        ServerStatusBeforeSplit serverStatus = new ServerStatusBeforeSplit();

        Thread thread1 = new Thread(() -> {
            for (int i = 0; i < 3; i++) {
                serverStatus.addUser("user" + (i+2));
                try { Thread.sleep(100); } catch (InterruptedException e) {}
            }
        });

        Thread thread2 = new Thread(() -> {
            for (int i = 0; i < 3; i++) {
                serverStatus.removeQuery("query" + i);
                try { Thread.sleep(200); } catch (InterruptedException e) {}
            }
        });

        // Start threads
        thread1.start();
        thread2.start();

        // Wait for threads to finish
        thread1.join();
        thread2.join();

        System.out.println("Users: " + serverStatus.users);
        System.out.println("Queries: " + serverStatus.queries);
    }
}

