public class MyAppThread extends Thread {

    private static final Logger LOGGER = Logger.getLogger(MyAppThread.class.getName());

    public static final String DEFAULT_NAME = "MyAppThread";
    private static final AtomicInteger created = new AtomicInteger();
    private static final AtomicInteger alive = new AtomicInteger();

    public static int getCreated() {
        return created.get();
    }

    public static int getAlive() {
        return alive.get();
    }

    public static void setDebug(boolean debug) {
        MyAppThread.debugLifecycle = debug;
    }

    private static volatile boolean debugLifecycle = false;

    public MyAppThread(String name, Runnable target) {
        super(target);
        setName(name + "-" + created.incrementAndGet());
    }

    @Override
    public void run() {
        try {
            if (debugLifecycle) {
                LOGGER.info("Created " + getName());
            }
            alive.incrementAndGet();
            super.run();
        } catch (Throwable cause) {
            Thread t = Thread.currentThread();
            String threadName = t.getName();

            if (t instanceof MyAppThread) {
                threadName += " [" + ((MyAppThread) t).getUncaughtExceptionHandler() + "]";
            }
            LOGGER.log(Level.SEVERE, threadName + " throws exception: ", cause);
        } finally {
            alive.decrementAndGet();
            if (debugLifecycle) {
                LOGGER.info("Terminated " + getName());
            }
        }
    }

    public static void main(String[] args) {

        Thread.currentThread().setUncaughtExceptionHandler((t, e) ->
            LOGGER.log(Level.SEVERE, t + " throws exception: ", e));

        ExecutorService executor = Executors.newFixedThreadPool(5);

        for (int i = 0; i < 3; i++) {
