        try (ExecutorService executor = Executors.newFixedThreadPool(poolSize)) {
            for(int i=0; i<poolSize; i++) {
                executor.submit(task);
            }
            executor.shutdown();
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.MILLISECONDS);
        }
    }

