    }

    public class InsufficientFundsException extends Exception {
        public InsufficientFundsException(String message) {
            super(message);
        }
    }

    private static final class TransferHelper {
        private void transfer(Account fromAccount, Account toAccount, DollarAmount amount)
                throws InsufficientFundsException {
            if (fromAccount.balance().getAmount() < amount.getAmount()) {
                throw new InsufficientFundsException("Insufficient funds in account");
            }

            fromAccount.debit(amount);
            toAccount.credit(amount);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        final Account account1 = new AccountImpl(1000);
        final Account account2 = new AccountImpl(500);

        executor.submit(() -> {
            try {
                new TransferHelper().transfer(account1, account2, new DollarAmount() {
                    @Override
                    public int getAmount() {
                        return 200;
                    }
                });
            } catch (InsufficientFundsException e) {
                System.out.println(e.getMessage());
            }
        });

        executor.submit(() -> {
            try {
                new TransferHelper().transfer(account2, account1, new DollarAmount() {
                    @Override
                    public int getAmount() {
                        return 800;
                    }
                });
            } catch (InsufficientFundsException e) {
                System.out.println(e.getMessage());
            }
        });

        executor.shutdown();
    }

    private static class AccountImpl implements Account {
        private final int accountNumber;
        private DollarAmount balance;

        public AccountImpl(int initialBalance) {
