            this.balance = new DollarAmount() {
                @Override
                public int getAmount() {
                    return initialBalance;
                }
            };
        }

        @Override
        public int getAccountNumber() {
            return accountNumber;
        }

        @Override
        public DollarAmount balance() {
            return balance;
        }

        @Override
        public void debit(DollarAmount amount) throws InsufficientFundsException {
            if (balance.getAmount() < amount.getAmount()) {
                throw new InsufficientFundsException("Insufficient funds to debit");
            }
            balance = new DollarAmount() {
                @Override
