public class MoneyTransfer {
    private static final ExecutorService executor = Executors.newFixedThreadPool(4);

    public static void main(String[] args) {
        Account aliceAccount = new Account();
        Account bobAccount = new Account();

        try {
            transferMoney(aliceAccount, bobAccount, 100);
        } catch (InterruptedException | ExecutionException e) {
            System.out.println("Failed to execute the transfer operation.");
        }

        executor.shutdown();
    }

    private static void transferMoney(Account from, Account to, int amount)
            throws InterruptedException, ExecutionException {
        if (from.hashCode() < to.hashCode()) {
            synchronized (from) {
                synchronized (to) {
                    transferMoneyHelper(from, to, amount);
                }
            }
        } else {
            synchronized (to) {
                synchronized (from) {
                    transferMoneyHelper(from, to, amount);
                }
            }
        }
    }

    private static void transferMoneyHelper(Account from, Account to, int amount)
            throws InterruptedException, ExecutionException {
        if (!from.hasSufficientFunds(amount)) throw new InsufficientFundsException();

        Callable<Void> debitFromAccount = () -> {
            from.debit(amount);
            return null;
        };

        Future<Void> creditToAccountFuture = executor.submit(debitFromAccount);

        Callable<Void> creditToAccount = () -> {
            to.credit(amount);
            return null;
        };

        executor.submit(creditToAccount);

        creditToAccountFuture.get();
    }
}

