            Node<Integer> next = currentTop.next.get();
            if (next != null) {
                if (top.compareAndSet(currentTop, next))
                    return currentTop.item;
            } else {
                if (top.compareAndSet(currentTop, next)) {
                    return currentTop.item;
                }
            }
        }
    }

