import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class NonBlockingStack {

    private static final int MAX_POOL_SIZE = 4;

    private static AtomicReference<Node> top = new AtomicReference<>(null);

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = new ThreadPoolExecutor(1, MAX_POOL_SIZE,
                Long.MAX_VALUE, TimeUnit.NANOSECONDS,
                new LinkedBlockingQueue<Runnable>());

        for (int i = 0; i < 2; ++i)
            executor.submit(new StackRunner());

        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);

        System.out.println("All threads finished. Stack operations completed.");
    }

    static class Node {
        final int item;
        AtomicReference<Node> next;

        Node(int item) {
            this.item = item;
            this.next = new AtomicReference<>(null);
        }
    }

    private static void push(Node node) {
        while (true) {
            Node currentTop = top.get();
            node.next.set(currentTop);
            if (top.compareAndSet(currentTop, node))
                return;
        }
    }

    private static Node pop() {
        while (true) {
            Node currentTop = top.get();
            if (currentTop == null)
                return null;

            if (top.compareAndSet(currentTop, currentTop.next.get()))
                return currentTop;
        }
    }

    private static class StackRunner implements Runnable {

        @Override
        public void run() {
            for (int i = 0; i < 5; ++i)
                push(new Node(i));

            for (int i = 0; i < 5; ++i) {
                Node node = pop();
                if (node != null)
                    System.out.println("Popped: " + node.item);
            }
        }
    }
}

import java.util.concurrent.*;

public class ConcurrentStack {

    private final AtomicReference<Node> top = new AtomicReference<>();

    static class Node {
        int item;
        Node next;

        public Node(int item, Node next) {
            this.item = item;
            this.next = next;
        }
    }

    public void push(int item) {
        Node newNode = new Node(item, null);
        while (true) {
            Node currentTop = top.get();
            newNode.next = currentTop;
            if (top.compareAndSet(currentTop, newNode)) {
                break;
            }
        }
    }

    public Integer pop() {
        while (true) {
            Node currentTop = top.get();
            if (currentTop == null) {
                return null;
            }
            Node nextNode = currentTop.next;
            if (top.compareAndSet(currentTop, nextNode)) {
                return currentTop.item;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ConcurrentStack stack = new ConcurrentStack();
        ExecutorService executor = Executors.newFixedThreadPool(4);

        // Push and pop operations in separate tasks
        for (int i = 0; i < 3; i++) {
            Runnable pushTask = () -> {
                for (int j = 0; j < 5; j++) {
                    stack.push(j);
                    System.out.println("Thread " + Thread.currentThread().getId() + " pushed: " + j);
                }
            };

            Runnable popTask = () -> {
                for (int j = 0; j < 5; j++) {
                    Integer poppedItem = stack.pop();
                    System.out.println("Thread " + Thread.currentThread().getId() + " popped: " + poppedItem);
                }
            };

            executor.execute(pushTask);
            executor.execute(popTask);
        }

        // Wait for all threads to finish
        executor.shutdown();
        while (!executor.isTerminated()) {
        }

        System.out.println("All operations completed.");
    }
}

