import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class DelegatingVehicleTracker {
    private final ConcurrentHashMap<String, Location> locations = new ConcurrentHashMap<>();

    public DelegatingVehicleTracker(Map<String, Location> initialLocations) {
        if(initialLocations != null){
            for(Map.Entry<String, Location> entry: initialLocations.entrySet()){
                this.locations.put(entry.getKey(), entry.getValue());
            }
        }
    }

    public Location getLocation(String vehicleId) {
        return locations.get(vehicleId);
    }

    public boolean setLocation(String vehicleId, Location newLocation) {
        if (locations.containsKey(vehicleId)) {
            locations.replace(vehicleId, newLocation);
            return true;
        } else {
            return false;
        }
    }

    public Map<String, Location> getAllLocations() {
        return locations; 
    }

    public Map<String, Location> getSnapshotAllLocations() {
        return java.util.Collections.unmodifiableMap(new ConcurrentHashMap<>(locations));
    }

