import java.util.*;
import java.util.concurrent.*;

public class ArkLoader {

    private enum Species {
        DOG,
        CAT,
        BIRD;
    }

    private enum Gender {
        MALE,
        FEMALE;
    }

    private static class Animal implements Comparable<Animal> {
        private final Species species;
        private final Gender gender;

        public Animal(Species species, Gender gender) {
            this.species = species;
            this.gender = gender;
        }

        @Override
        public int compareTo(Animal other) {
            if (!this.species.equals(other.species)) {
                return this.species.compareTo(other.species);
            }
            return this.gender.compareTo(other.gender);
        }
    }

    private static class AnimalPair {
        private final Animal male;
        private final Animal female;

        public AnimalPair(Animal male, Animal female) {
            this.male = male;
            this.female = female;
        }
    }

    private static class Ark {
        private List<AnimalPair> pairs = new ArrayList<>();

        public synchronized void addPair(AnimalPair pair) {
            this.pairs.add(pair);
        }

        public synchronized int getNumPairs() {
            return this.pairs.size();
        }
    }

    public static int loadTheArk(Collection<Animal> candidates, ExecutorService executorService) throws InterruptedException, ExecutionException {
        final List<Animal> sortedAnimals = new ArrayList<>(candidates);
        Collections.sort(sortedAnimals);

        Ark ark = new Ark();
        CountDownLatch latch = new CountDownLatch(sortedAnimals.size() / 2);

        for (int i = 0; i < sortedAnimals.size(); i += 2) {
            final Animal male = sortedAnimals.get(i);
            final Animal female = sortedAnimals.get(i + 1);

            Future<?> future = executorService.submit(new Callable<Void>() {
                @Override
                public Void call() throws Exception {
                    if (male.gender == Gender.MALE && female.gender == Gender.FEMALE &&
                            male.species == female.species) {

                        ark.addPair(new AnimalPair(male, female));
                    }
                    latch.countDown();
                    return null;
                }
            });
        }

        latch.await();

        executorService.shutdown();
        return ark.getNumPairs();
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        Collection<Animal> animals = Arrays.asList(
                new Animal(Species.DOG, Gender.MALE),
                new Animal(Species.CAT, Gender.FEMALE),
                new Animal(Species.BIRD, Gender.MALE),
                new Animal(Species.DOG, Gender.FEMALE)
        );

        ExecutorService executorService = Executors.newFixedThreadPool(2);
        int numPairs = loadTheArk(animals, executorService);
        System.out.println("Number of pairs: " + numPairs);
    }
}

