class PrimeProducer extends Thread {
    private final BlockingQueue<Integer> queue;
    private int primesGenerated = 0;

    public PrimeProducer(BlockingQueue<Integer> queue, String name) {
        super(name);
        this.queue = queue;
    }

    @Override
    public void run() {
        try {
            while (primesGenerated < 2 && !Thread.currentThread().isInterrupted()) {
                int prime1 = generatePrimeNumber();
                int prime2 = generatePrimeNumber();

                if (prime1 != -1 && prime2 != -1) {
                    queue.put(prime1);
                    queue.put(prime2);

                    primesGenerated++;
                }
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Reassert the interrupt status
        } finally {
            queue.offer(null); // Indicate end of production if interrupted or enough primes have been produced
        }
    }

    private int generatePrimeNumber() {
        for (int i = 2; true; i++) { 
            boolean isPrime = checkIfPrime(i);

            if (isPrime) {
                return i;
            }
        }
    }

    private static boolean checkIfPrime(int numberToCheck) {
        if(numberToCheck <= 1)
            return false;

        for (int j = 2; j * j <= numberToCheck; j++) {
            if (numberToCheck % j == 0) 
                return false;
        }

        return true;
    }
}

