import java.util.*;
import java.util.concurrent.*;

interface Element {
    void process();
}

class Node implements Element {
    private List<Node> children = new ArrayList<>();

    public void addChild(Node child){
        this.children.add(child);
    }

    @Override
    public void process(){
        for (Node child : this.children){
            child.process();
        }
    }

    public CompletableFuture<Void> processAsync(ExecutorService executor) {
        List<CompletableFuture<Void>> futures = new ArrayList<>();

        for (Node child : this.children){
            futures.add(CompletableFuture.runAsync(() -> child.process(), executor));
        }

        return CompletableFixed.allOf(futures.toArray(new CompletableFuture[0])).thenRun(() -> System.out.println("All nodes processed"));
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException, ExecutionException {
