        Node root = new Node();
        for (int i=0; i<3; i++){
            Node child = new Node();
            root.addChild(child);
        }

        CompletableFuture<Void> future = root.processAsync(executor);
        future.get(); // wait until all tasks are completed

        executor.shutdownNow();
    }
}

