        if (root == null || processor == null) throw new IllegalArgumentException("Invalid arguments");

        List<Node<?>> children = root.getChildren();

        for (Node<?> node : children) {
            try {
                processor.process(node);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw e;
            }
        }

        for (Node<?> node : children) {
            processSequentially(node, processor);
        }
    }

    public static void parallelProcess(Node<?> root, ElementProcessor processor, ExecutorService executor)
            throws InterruptedException, ExecutionException {
