    }

    @Override
    public V get(Object key) {
        rwl.readLock().lock();
        try {
            return map.get(key);
        } finally {
            rwl.readLock().unlock();
        }
    }

    @Override
    public int size() {
        rwl.readLock().lock();
        try {
            return map.size();
        } finally {
            rwl.readLock().unlock();
        }
    }

